import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C' if rng.random() < 0.9 else 'D'
    coop = sum(1 for me, opp in history if me == 'C' and opp == 'C')
    bothd = sum(1 for me, opp in history if me == 'D' and opp == 'D')
    cd = sum(1 for me, opp in history if me == 'C' and opp == 'D')
    dc = sum(1 for me, opp in history if me == 'D' and opp == 'C')
    last_me, last_opp = history[-1]
    if n < 3:
        return 'C'
    if last_opp == 'D':
        if last_me == 'C' and rng.random() < 0.7:
            return 'D'
        if last_me == 'D' and rng.random() < 0.25:
            return 'C'
        return 'D'
    if n >= 3:
        recent = history[-3:]
        if all(me == 'C' and opp == 'D' for me, opp in recent):
            return 'D'
    if dc > 0 and cd == 0 and last_opp == 'C':
        if rng.random() < 0.85:
            return 'D'
    if coop > 0 and cd * 2 > coop and last_opp == 'C':
        if rng.random() < 0.6:
            return 'D'
    if bothd > 2 and last_opp == 'C':
        if rng.random() < 0.4:
            return 'C'
    if n > 90:
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    return 'C' if rng.random() < 0.92 else 'D'
